begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_app_meta_data) select
 ('b1800000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'identity-'||n||'@example.test',
 case when n=4 then '{"role":"admin"}'::jsonb else '{"merchant_enabled":true}'::jsonb end from generate_series(1,4)n;
insert into public.profiles(id,nickname,city_id,terms_accepted_at,privacy_accepted_at,ai_safety_consent_at,consent_version)
 select ('b1800000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'비즈니스신원검사'||n,'vancouver',now(),now(),now(),'test' from generate_series(1,4)n;
insert into auth.sessions(id,user_id,aal) values('b1890000-0000-4000-8000-000000000004','b1800000-0000-4000-8000-000000000004','aal2');
insert into private.merchants(id,name,city_id,contact,status,consent,consent_note,record_kind,owner_id,owner_verified_at,trial_ends_at)
 values('b1810000-0000-4000-8000-000000000001','지모코신원검사','vancouver','','trial','granted','synthetic fixture','business','b1800000-0000-4000-8000-000000000001',now(),current_date+2);
insert into private.merchant_operators(merchant_id,user_id,created_by) values('b1810000-0000-4000-8000-000000000001','b1800000-0000-4000-8000-000000000002','b1800000-0000-4000-8000-000000000004');
insert into private.merchant_workspace_drafts(id,merchant_id,channel,title,body,tag_slug,kind,approved_at,approved_by)
 select ('b1830000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'b1810000-0000-4000-8000-000000000001','gling','신원검사 안내 '||n,'실제 홍보가 아닌 합성 검사 원고 '||n,'life','story',now(),('b1800000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,2)n;
select set_config('request.jwt.claims','{"sub":"b1800000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.publish_merchant_workspace_draft('b1810000-0000-4000-8000-000000000001','b1830000-0000-4000-8000-000000000001',now())$$,'verified owner publishes through existing protected writer');
reset role;
select set_config('request.jwt.claims','{"sub":"b1800000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.publish_merchant_workspace_draft('b1810000-0000-4000-8000-000000000001','b1830000-0000-4000-8000-000000000002',now())$$,'connected operator publishes through existing protected writer');
reset role;
select set_config('test.business_post',(select post_id::text from private.merchant_workspace_drafts where id='b1830000-0000-4000-8000-000000000001'),true);
select is((select count(*) from private.merchant_posts where merchant_id='b1810000-0000-4000-8000-000000000001' and published_as_business),2::bigint,'both business writers bind explicit official identity');
select is((select p.author_id from public.posts p where p.id=current_setting('test.business_post')::uuid),'b1800000-0000-4000-8000-000000000001'::uuid,'real human author remains available to moderation');
insert into public.posts(id,author_id,city_id,tag_id,title,body) values('b1820000-0000-4000-8000-000000000003','b1800000-0000-4000-8000-000000000003','vancouver',1,'개인 소개글','합성 개인 글');
insert into private.merchant_posts(post_id,merchant_id,creation_request_id) values('b1820000-0000-4000-8000-000000000003','b1810000-0000-4000-8000-000000000001','b1830000-0000-4000-8000-000000000003');
select is(jsonb_array_length(public.get_public_post_businesses(array['b1820000-0000-4000-8000-000000000003']::uuid[])),0,'admin-curated personal posts never impersonate a business');
update private.merchants set status='lead' where id='b1810000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select is(public.get_public_post_businesses(array[current_setting('test.business_post')::uuid])->0->>'business_name','지모코신원검사','basic business retains its official public identity');
select is((select count(*)::integer from jsonb_object_keys(public.get_public_post_businesses(array[current_setting('test.business_post')::uuid])->0)),3,'public identity exposes only post id and business id/name');
select is(public.get_merchant_profile('b1810000-0000-4000-8000-000000000001')->>'name','지모코신원검사','official business author opens its public profile');
select is(public.get_merchant_profile('b1810000-0000-4000-8000-000000000001')->>'review_post_id',null::text,'business identity never grants paid review privileges');
select is(public.get_merchant_profile_posts('b1810000-0000-4000-8000-000000000001')->>'post_count','2','business profile lists official posts, excludes curated basic posts');
select is((select count(*) from public.get_public_feed_page_v2('vancouver',null::smallint,'지모코신원검사',null::timestamptz,null::uuid,30)),2::bigint,'official business name is searchable without changing feed visibility');
select throws_ok($$select public.get_public_post_businesses(array_fill(gen_random_uuid(),array[51]))$$,'P0001','INVALID_BUSINESS_POST_PAGE','public batch is bounded');
select throws_ok($$select public.get_public_post_businesses(array[null]::uuid[])$$,'P0001','INVALID_BUSINESS_POST_PAGE','null post identifiers rejected');
reset role;
update public.posts set status='removed' where id=current_setting('test.business_post')::uuid;
select is(jsonb_array_length(public.get_public_post_businesses(array[current_setting('test.business_post')::uuid])),0,'hidden posts expose no business identity');
update public.posts set status='published' where id=current_setting('test.business_post')::uuid;
update public.profiles set account_status='suspended' where id='b1800000-0000-4000-8000-000000000001';
select is(jsonb_array_length(public.get_public_post_businesses(array[current_setting('test.business_post')::uuid])),0,'suspended human author exposes no business identity');
update public.profiles set account_status='active' where id='b1800000-0000-4000-8000-000000000001';
update private.merchants set status='paused' where id='b1810000-0000-4000-8000-000000000001';
select is(jsonb_array_length(public.get_public_post_businesses(array[current_setting('test.business_post')::uuid])),0,'paused business exposes no identity');
update private.merchants set status='lead',consent='revoked' where id='b1810000-0000-4000-8000-000000000001';
select is(jsonb_array_length(public.get_public_post_businesses(array[current_setting('test.business_post')::uuid])),0,'revoked consent exposes no identity');
update private.merchants set consent='granted',record_kind='source' where id='b1810000-0000-4000-8000-000000000001';
select is(jsonb_array_length(public.get_public_post_businesses(array[current_setting('test.business_post')::uuid])),0,'source records expose no business identity');
update private.merchants set record_kind='business',deleted_at=now() where id='b1810000-0000-4000-8000-000000000001';
select is(jsonb_array_length(public.get_public_post_businesses(array[current_setting('test.business_post')::uuid])),0,'deleted business exposes no identity');
update private.merchants set deleted_at=null where id='b1810000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"sub":"b1800000-0000-4000-8000-000000000003","role":"authenticated"}',true);
insert into public.blocks(blocker_id,blocked_id) values('b1800000-0000-4000-8000-000000000003','b1800000-0000-4000-8000-000000000001');
select is(jsonb_array_length(public.get_public_post_businesses(array[current_setting('test.business_post')::uuid])),0,'block relationship remains effective');
delete from public.blocks where blocker_id='b1800000-0000-4000-8000-000000000003';
delete from public.reports where reporter_id='b1800000-0000-4000-8000-000000000003';
insert into public.reports(reporter_id,reported_user_id,target_type,target_id,reason_code) values('b1800000-0000-4000-8000-000000000003','b1800000-0000-4000-8000-000000000001','user','b1800000-0000-4000-8000-000000000001','spam');
select is(jsonb_array_length(public.get_public_post_businesses(array[current_setting('test.business_post')::uuid])),0,'reported actor remains excluded');
delete from public.reports where reporter_id='b1800000-0000-4000-8000-000000000003';
insert into public.reports(reporter_id,reported_user_id,target_type,target_id,reason_code) values('b1800000-0000-4000-8000-000000000003','b1800000-0000-4000-8000-000000000001','post',current_setting('test.business_post')::uuid,'spam');
select is(jsonb_array_length(public.get_public_post_businesses(array[current_setting('test.business_post')::uuid])),0,'reported post remains excluded');
select ok(not has_function_privilege('anon','public.get_admin_user_businesses(uuid)','execute'),'business links remain private admin data');
select ok(not has_function_privilege('authenticated','private.public_post_business_id(uuid)','execute'),'private helper cannot bypass public DTO boundary');
select is(private.promotion_fingerprint('동일 본문'||E'\n\n업체에서 직접 게시한 안내입니다.'),private.promotion_fingerprint('동일 본문'||E'\n\n비즈니스에서 직접 게시한 안내입니다.'),'terminology changes preserve historical duplicate fingerprints');
select is(private.promotion_fingerprint('동일 본문'||E'\n\n업체의 허락을 받아 글링에서 대신 게시한 안내입니다.'),private.promotion_fingerprint('동일 본문'||E'\n\n비즈니스의 허락을 받아 글링에서 대신 게시한 안내입니다.'),'delegated publication disclosure keeps its historical fingerprint');
select ok(position('업체' in pg_get_functiondef('public.create_admin_merchant_post(uuid,text,text,text,text,text,uuid)'::regprocedure))=0,'future admin disclosures use business terminology');
set local role authenticated;
select throws_ok($$select public.get_admin_user_businesses('b1800000-0000-4000-8000-000000000001')$$,'P0001','ADMIN_REQUIRED','ordinary member cannot inspect another account connections');
reset role;
select set_config('request.jwt.claims','{"sub":"b1800000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2","session_id":"b1890000-0000-4000-8000-000000000004","app_metadata":{"role":"admin"}}',true);
set local role authenticated;
select is(public.get_admin_user_businesses('b1800000-0000-4000-8000-000000000001')->'businesses'->0->>'role','owner','elevated admin sees exact target owner role');
select is(public.get_admin_user_businesses('b1800000-0000-4000-8000-000000000002')->'businesses'->0->>'role','operator','elevated admin sees exact target operator role');
reset role;
select ok(exists(select 1 from public.admin_access_logs where actor_id='b1800000-0000-4000-8000-000000000004' and subject_user_id='b1800000-0000-4000-8000-000000000002'),'admin connection reads remain audited');
update private.merchants set record_kind='source' where id='b1810000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.get_admin_user_businesses('b1800000-0000-4000-8000-000000000001')->'businesses','[]'::jsonb,'source records are excluded from user business connections');
select throws_ok($$select public.connect_admin_merchant_account('b1810000-0000-4000-8000-000000000001','b1800000-0000-4000-8000-000000000003','operator','direct',true,'synthetic confirmed check',now(),'비즈니스신원검사3','identity-3@example.test')$$,'P0001','MERCHANT_NOT_FOUND','source records cannot gain account connections');
reset role;
select * from finish();
rollback;
